CustomField.formula:
IF(ISNULL(NumberOfEmployees), 0,
  IF(NumberOfEmployees >= 1000, 30,
    IF(NumberOfEmployees >= 200, 25,
      IF(NumberOfEmployees >= 51, 15,
        IF(NumberOfEmployees >= 11, 10, 5)
      )
    )
  )
) +
IF(NOT(ISPICKVAL(Industry, "")), 15, 0) +
IF(NOT(ISBLANK(Phone)), 10, 0) +
IF(NOT(ISBLANK(Title)), 15, 0) +
IF(
  AND(
    NOT(ISBLANK(Email)),
    NOT(OR(
      CONTAINS(Email, 'gmail.com'),
      CONTAINS(Email, 'yahoo.com'),
      CONTAINS(Email, 'hotmail.com'),
      CONTAINS(Email, 'outlook.com')
    ))
  ), 20, 0
)
